-- Repair a production database where the growth foundation was recorded in
-- Prisma history before its schema changes were applied. Everything is
-- additive and idempotent: existing business data is left untouched.
CREATE TABLE IF NOT EXISTS "growth_visitors" ("id" TEXT PRIMARY KEY, "user_id" INTEGER, "first_touch" JSONB NOT NULL, "last_touch" JSONB NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "growth_visitors_user_id_created_at_idx" ON "growth_visitors"("user_id", "created_at");
CREATE TABLE IF NOT EXISTS "growth_events" ("id" TEXT PRIMARY KEY, "key" TEXT NOT NULL UNIQUE, "event" TEXT NOT NULL, "user_id" INTEGER, "visitor_id" TEXT, "source" TEXT NOT NULL, "campaign" TEXT, "properties" JSONB, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "growth_events_event_created_at_idx" ON "growth_events"("event", "created_at");
CREATE INDEX IF NOT EXISTS "growth_events_campaign_created_at_idx" ON "growth_events"("campaign", "created_at");
CREATE INDEX IF NOT EXISTS "growth_events_user_id_event_idx" ON "growth_events"("user_id", "event");
CREATE TABLE IF NOT EXISTS "marketing_campaigns" ("id" SERIAL PRIMARY KEY, "slug" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "channel" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'draft', "landing_page" TEXT NOT NULL, "source" TEXT NOT NULL, "medium" TEXT NOT NULL, "content" TEXT NOT NULL DEFAULT '', "budget_cents" INTEGER NOT NULL DEFAULT 0 CHECK ("budget_cents" >= 0), "notes" TEXT NOT NULL DEFAULT '', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "campaign_spend" ("id" TEXT PRIMARY KEY, "campaign_id" INTEGER NOT NULL REFERENCES "marketing_campaigns"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "amount_cents" INTEGER NOT NULL CHECK ("amount_cents" > 0), "spent_at" TIMESTAMP(3) NOT NULL, "note" TEXT NOT NULL, "actor_id" INTEGER, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "campaign_spend_campaign_id_spent_at_idx" ON "campaign_spend"("campaign_id", "spent_at");
CREATE TABLE IF NOT EXISTS "growth_leads" ("id" SERIAL PRIMARY KEY, "kind" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT, "company" TEXT, "interest" TEXT NOT NULL, "message" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'new', "user_id" INTEGER, "visitor_id" TEXT, "attribution" JSONB, "notes" TEXT NOT NULL DEFAULT '', "assigned_to" INTEGER, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "growth_leads_kind_status_created_at_idx" ON "growth_leads"("kind", "status", "created_at");
CREATE TABLE IF NOT EXISTS "growth_reward_policy" ("id" INTEGER PRIMARY KEY DEFAULT 1, "artist_credit" INTEGER NOT NULL DEFAULT 100 CHECK ("artist_credit" >= 0), "half_yearly_commission" INTEGER NOT NULL DEFAULT 75 CHECK ("half_yearly_commission" >= 0), "annual_commission" INTEGER NOT NULL DEFAULT 150 CHECK ("annual_commission" >= 0), "label_commission" INTEGER NOT NULL DEFAULT 200 CHECK ("label_commission" >= 0), "cooling_days" INTEGER NOT NULL DEFAULT 7 CHECK ("cooling_days" >= 1), "payout_minimum" INTEGER NOT NULL DEFAULT 500 CHECK ("payout_minimum" >= 0), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO "growth_reward_policy"("id") VALUES (1) ON CONFLICT ("id") DO NOTHING;
ALTER TABLE "referrals" ADD COLUMN IF NOT EXISTS "reward_policy" JSONB;
CREATE TABLE IF NOT EXISTS "growth_partners" ("id" SERIAL PRIMARY KEY, "lead_id" INTEGER NOT NULL UNIQUE, "code" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'approved', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "partner_referrals" ("id" SERIAL PRIMARY KEY, "partner_id" INTEGER NOT NULL REFERENCES "growth_partners"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "user_id" INTEGER NOT NULL UNIQUE, "policy" JSONB NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "partner_rewards" ("id" SERIAL PRIMARY KEY, "referral_id" INTEGER NOT NULL UNIQUE REFERENCES "partner_referrals"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "subscription_payment_id" INTEGER NOT NULL UNIQUE, "amount" INTEGER NOT NULL CHECK ("amount" >= 0), "plan" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "eligible_at" TIMESTAMP(3) NOT NULL, "approved_at" TIMESTAMP(3), "paid_at" TIMESTAMP(3), "payout_reference" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "partner_rewards_status_eligible_at_idx" ON "partner_rewards"("status", "eligible_at");
CREATE TABLE IF NOT EXISTS "growth_communication_preferences" ("user_id" INTEGER PRIMARY KEY, "reminders" BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS "growth_nudges" ("key" TEXT PRIMARY KEY, "user_id" INTEGER NOT NULL, "release_id" INTEGER NOT NULL, "stage" INTEGER NOT NULL, "due_at" TIMESTAMP(3) NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending');
CREATE INDEX IF NOT EXISTS "growth_nudges_status_due_at_idx" ON "growth_nudges"("status", "due_at");
